  'Reconnect and reconcile': '重新连接并核对状态',
  'Remote session reconciled. Review the remote transcript before sending again.': '远程会话状态已核对。再次发送前请查看远程记录。',
  'Replay gap: showing a fresh remote snapshot.': '重放存在缺口：显示新的远程快照。',
  "Full access: Hermes still asks you in the chat when it wants an approval. Its own rules apply there.": "完全权限：Hermes 需要审批时仍会在聊天中询问你。那台电脑上适用它自己的规则。",
  "Agent access": "智能体访问",
  "Let an agent outside Automagik, like Claude Code on your laptop, read your chats and set up your Bots. Each agent gets a key of its own, and you can revoke it at any time.": "让 Automagik 之外的智能体（比如你笔记本上的 Claude Code）读取你的对话并配置你的 Bot。每个智能体有自己的密钥，你可以随时撤销。",
  "Agent keys": "访问密钥",
  "Agent keys · {count}": "访问密钥 · {count}",
  "Name for the new key": "新密钥的名称",
  "Name, e.g. Claude Code": "名称，例如 Claude Code",
  "Create key": "创建密钥",
  "Give the key a name first.": "请先给密钥起个名字。",
  "Use plain letters (a–z), numbers, spaces, dots and dashes, up to 60.": "请使用英文字母（a–z）、数字、空格、点和短横线，最多 60 个字符。",
  "Key created for {name}": "已为 {name} 创建密钥",
  "Copy the key": "复制密钥",
  "Copy it now. You will not see this key again.": "请现在复制。这个密钥之后不会再显示。",
  "Copying did not work here. Select the key and copy it by hand. You will not see it again.": "这里无法自动复制。请选中密钥手动复制，之后不会再显示。",
  "No keys yet. Create one for each agent you let in, so you can revoke them one by one.": "还没有密钥。为每个要放行的智能体各创建一个，这样可以逐个撤销。",
  "Created {date}": "创建于 {date}",
  "Last used {time}": "上次使用 {time}",
  "Not used yet": "还没用过",
