  "Revoke": "撤销",
  "Revoke {name}": "撤销 {name}",
  "Revoke {name}? The agent using it loses access at once.": "撤销 {name}？使用它的智能体会立刻失去访问权限。",
  "Show {count} older revoked keys": "显示另外 {count} 个更早撤销的密钥",
  "Connect an agent": "连接智能体",
  "Create a key first. The address and an example setup then show here.": "请先创建密钥。地址和配置示例随后会显示在这里。",
  "Web address": "网页地址",
  "For an agent on any computer that can open this page.": "适用于任何能打开此页面的电脑上的智能体。",
  "Direct address": "直连地址",
  "Copy the address": "复制地址",
  "Only this computer: agents elsewhere cannot reach this address.": "仅限这台电脑：其他地方的智能体无法访问这个地址。",
  "Only the computer Automagik runs on: agents elsewhere cannot reach this address.": "仅限运行 Automagik 的电脑：其他地方的智能体无法访问这个地址。",
  "Private network: agents on your private network can connect.": "专用网络：你专用网络里的智能体可以连接。",
  "Example setup": "配置示例",
  "For Claude Code, in a file named .mcp.json. Other agents ask for the same address and key.": "适用于 Claude Code，写在名为 .mcp.json 的文件里。其他智能体需要的也是同样的地址和密钥。",
  "Copy the example": "复制示例",
  "Put your key in place of {placeholder}. Keep the file out of anything you share.": "把 {placeholder} 换成你的密钥。不要把这个文件放进会分享出去的地方。",
  "Access log": "访问记录",
  "What agents did with their keys": "智能体用密钥做了什么",
  "Newest first. The latest 200 show here.": "最新的在前。这里显示最近 200 条。",
  "Show the log of": "查看哪个密钥的记录",
  "All keys": "所有密钥",
  "Unknown key": "未知密钥",
  "Refresh": "刷新",
  "Nothing yet. What an agent does with a key is listed here.": "还没有记录。智能体用密钥做的事会列在这里。",
  "Nothing from this key in the latest 200.": "最近 200 条里没有这个密钥的记录。",
  "Refused": "已拒绝",
