  'Cache ratio unavailable: missing fields or incompatible normalization.': '无法计算缓存比例：字段缺失或统计口径不兼容。',
  'Input is reported input; unknown is not zero. Cache ratios use compatible prompt-token denominators, separately by provider.': '输入为服务商报告的输入；未知不等于零。缓存比例按服务商分别计算，且只使用兼容的提示词 token 分母。',
  'Request and turn scopes include attributable attempts only. Unlinked memory, steward, checkpoint, handoff and child overhead remain in Session or Bot totals. Scopes overlap; do not add them together.': '请求和轮次只计入可归属的调用。未关联的记忆、上下文管家、检查点、交接和子任务开销保留在会话或 Bot 总计中。各范围有重叠，请勿相加。',
  'Accounting refresh in progress; totals may be incomplete.': '正在刷新统计，总计可能尚不完整。',
  'Partial accounting: some Session history could not be read.': '统计不完整：部分会话历史无法读取。',
  'Tokens and attempts only. Cache efficiency is not task success; no cost, timing or native-DSH effectiveness comparison is inferred.': '只统计 token 和调用尝试。缓存效率不代表任务成功，也不推断费用、耗时或与原生 DSH 的效果对比。',
  'Advanced': '高级',
  'Advanced Bot': '高级 Bot 模式',
  'Show supported native DSH controls, Context and Stats for this Bot. This switch changes visibility only, not permissions, model access or context policy.': '显示此 Bot 支持的原生 DSH 控件、上下文与统计。此开关只改变显示，不改变权限、模型访问或上下文策略。',
  'Context': '上下文',
  'Current part': '当前部分',
  'Checkpoints': '检查点',
  'Usable window': '可用窗口',
  'Check line': '检查阈值',
  'Hard safety': '硬安全阈值',
  'Effective model window is unavailable until a request header is known.': '获取请求头之前，无法确定模型的有效窗口。',
  'Check at (% usable window)': '检查阈值（可用窗口百分比）',
  'Per-Bot override. Default 80%; must stay below the protected 95% hard line.': '仅覆盖此 Bot。默认 80%，必须低于受保护的 95% 硬阈值。',
  'Recent-message carry budget': '最近消息保留预算',
  'Token budget for protected recent messages in checkpoints and handoffs; the effective budget is also capped by the check line.': '检查点与交接中保留最近消息的 token 预算；实际预算也受检查阈值限制。',
  'Use context defaults': '使用默认上下文设置',
  'Checkpoint now': '立即创建检查点',
  'Confirm new part': '确认开始新部分',
  'Start new part': '开始新部分',
  'Start new part carries nothing from this part. Earlier history remains searchable. Click Confirm new part to continue.': '新部分不会携带本部分内容。旧历史仍可搜索。点击“确认开始新部分”继续。',
  'Checkpoint now condenses this part while keeping protected recent messages. Start new part is separate and carries nothing. Native manual compaction is unavailable for Bot-managed Sessions.': '立即创建检查点会压缩本部分，并保留受保护的最近消息。开始新部分是独立操作，不携带旧内容。Bot 管理的会话不支持原生手动压缩。',
  'Memory review': '记忆审核',
  'Automatic memory review': '自动记忆审核',
  'Reviews this Bot’s own chat after idle turns. Independent of context compaction; no fixed ordering is promised.': '在空闲轮次后审核此 Bot 的私聊。与上下文压缩独立，不保证固定顺序。',
  'Automatic memory review is disabled by the host configuration.': '主机配置已禁用自动记忆审核。',
  'Memory review running. Disabling review prevents future passes; this pass may finish.': '记忆审核正在运行。关闭后不再启动后续审核，本次审核仍可能完成。',
  'Memory review pending.': '记忆审核等待中。',
  'Memory review idle.': '记忆审核空闲。',
  'Automatic memory review is off for this Bot.': '此 Bot 已关闭自动记忆审核。',
  'Memory tidy': '记忆整理',
  'Daily memory tidy': '每日记忆整理',
  'Once a day, when this Bot’s own memory has changed, its model merges repeats, retires what is over and moves details into topics. It uses tokens every day, so it is off until you turn it on. The memory panel can undo the latest tidy.': '每天一次，当此 Bot 自己的记忆有变化时，由它的模型合并重复条目、归档已结束的内容，并把细节移入主题。每天都会消耗令牌，因此默认关闭，需手动开启。可在记忆面板撤销最近一次整理。',
  'The daily memory tidy is disabled by the host configuration.': '主机配置已禁用每日记忆整理。',
  'The host configuration runs the daily memory tidy for every memory.': '主机配置已为所有记忆开启每日记忆整理。',
  'The daily memory tidy is on for this Bot.': '此 Bot 已开启每日记忆整理。',
  'The daily memory tidy is off for this Bot.': '此 Bot 已关闭每日记忆整理。',
