  'An OPENAI_API_KEY from the environment is not used for images. Sign in to Codex from a Bot\'s chat, or save that key in Settings → Models.': '环境中的 OPENAI_API_KEY 不会用于图片。请在 Bot 的聊天中登录 Codex，或将该密钥保存在设置 → 模型中。',
