export function t(key, params) {
  return bound ? bound(key, params) : fill(key, params)
}

// Host messages with values in them (the model access refusals, models.js ACCESS_MESSAGES, and
// a model switch DSH turned down, roster.js): the template is the dictionary key, worded with
// the values the message carried.
const HOST_TEMPLATES = [
  GUARD_GROUP_COPY.join,
  GUARD_GROUP_COPY.inGroup,
  "{name} cannot use start_task: its review guard is on. Do the work in your own chat, or ask the person to turn the review guard off in {name}'s Details.",
  "The model {model} cannot run a task now.",
  "{model} could not be selected for the task.",
  { template: "The task did not start: {reason}", host: ['reason'] },
  "The model {model} is not in the list of models.",
  "{model} runs only through its coding CLI; name its CLI model.",
  "Models you may name: {models} and {n} more.",
  "Models you may name: none; leave out model.",
  "Models you may name: {models}.",
  "The skill {name} is not active on this Bot. Add it in the Bot's Details, under Skills.",
  { template: "Not saved: {reason} (line {line}). Change the text and save again.", host: ["reason"] },
  { template: "Not saved: {reason} (line {line}). Name the key in the skill and set its value in Apps or Secrets.", host: ["reason"] },
  "A skill named {name} already exists. Edit it, or choose another name.",
  "The name {name} is reserved for the /{name} command. Choose another name.",
  { template: "{name} is held: {reason} Open it on the Skills screen and save it again.", host: ["reason"] },
  'Detach {name} first.',
  "{name} is already moving to a new conversation.",
  "{name} is still handing on earlier messages; try again shortly.",
  "Answer or dismiss {name}'s open card first.",
  "Pause {name}'s goal first.",
  "Wait for {name} to finish, then share it.",
  "{name} has messages waiting; let them run or remove them, then share it.",
  "{issuer} {subject} has not signed in since the last restart, or not as a {role}",
  "Who may talk to {name} changed in another window; check it and save again.",
  'A folder is in the way: {folder}',
  '{name} does not have the {tool} tool: its Genie role is off.',
  'This connection’s saved Hermes profile “{profile}” is not served there. Choose a profile again before connecting.',
  'This step is hard to undo: {step}. Allow it once?',
  '{name} was refused {count} times in this turn, the last time on {tool}. Let it keep working?',
  'Turn on {connection} in Settings → Coding agents before using this model.',
  'Wait for {connection} to finish installing, or retry it in Settings → Coding agents.',
  'Sign in to {connection} before using this model.',
  'Confirm the account of {connection} before using this model.',
  // A host sign-in refusal with no sentence of its own carries its ACP class.
  'Could not continue this sign-in ({kind}). Try again.',
  'The account could not be confirmed ({kind}). Try again.',
  'This account is reserved for {label} by another installation that shares this team.',
  MACHINE_MESSAGES.refused,
  MACHINE_MESSAGES['no-organisation'],
  MACHINE_MESSAGES['unknown-plan'],
  MACHINE_MESSAGES.conflict,
  '{name} could not switch to {model}. It stays on {kept}.',
  // A pick that would stop a running reply (reason reply-running): the selector asks first.
  { template: 'This stops the current reply and continues on {agent}.', host: ['agent'] },
  { template: '{name} cannot use the {route} route.', host: ['route'] },
  { template: "{name}'s conversation has history, so changing to {route} needs a new conversation. Use New conversation, then pick {route} (pause an active goal first).", host: ['route'] },
  { template: "{name}'s conversation has history, so changing to {route} needs a new conversation. Use New conversation, then pick {route}.", host: ['route'] },
  // A Bot Session adopt refused after it began (#877). `host`: a value that is itself a host
  // message (the store's read-only reason) is worded in turn.
  { template: 'Session {session} cannot join {bot} because this window cannot change the Bot team now. {reason}', host: ['reason'] },
  '{bot} changed while Session {session} was joining it (another window or an edit). For the Bot team: Nothing was changed; try again. The native preset of Session {session} was set to "{preset}" before this refusal.',
  '{bot} changed while Session {session} was being saved. For the Bot team: Nothing was changed; try again. The native preset of Session {session} was set to "{preset}" before this refusal.',
  // The roster's not-installed reasons (installed.js): the plugin name, and the load error's
  // code when DSH gave one, are values in the message.
  'the {name} plugin is missing from this DSH',
  'the {name} plugin is switched off in this DSH',
  'the {name} plugin did not load in this DSH ({code})',
  'the {name} plugin did not load in this DSH',
  // Auto's refusals that name the Bot (auto.js setBotAuto).
  "{name}'s permissions changed meanwhile, so nothing was saved. Look again and choose.",
  'Auto is not offered for {name} here.',
].map((entry) => {
  const { template, host = [] } = typeof entry === 'string' ? { template: entry } : entry
  const names = []
  const source = template.split(/(\{\w+\})/).map((part) => {
    const name = /^\{(\w+)\}$/.exec(part)?.[1]
    if (name === undefined) return part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    names.push(name)
    return '(.+?)'
  }).join('')
  return { template, names, host, pattern: new RegExp(`^${source}$`) }
})
export function hostTemplateOf(message) {
  return HOST_TEMPLATES.find(({ pattern }) => pattern.test(message))?.template
}
function hostTemplate(message) {
  const matched = hostTemplateOf(message)
  if (matched === undefined) return undefined
  const { template, names, host, pattern } = HOST_TEMPLATES.find(entry => entry.template === matched)
  const found = pattern.exec(message)
  return t(template, Object.fromEntries(names.map((name, index) => [name, host.includes(name) ? hostText(found[index + 1]) : found[index + 1]])))
}

// A message from the host, in the interface language.
export function hostText(message) {
  if (message === 'desktop-only') return t('Terminals show in the Automagik desktop app.')
  if (typeof message === 'string' && (bound || language().startsWith('zh'))) {
    const worded = hostTemplate(message)
    if (worded !== undefined) return worded
  }
  // A language pack that words this message (any language: the pt-BR pack, a plugin's
  // addStrings) wins; the patterns below are for Chinese only.
  if (bound && typeof message === 'string') {
    const worded = t(message)
    if (worded !== message) return worded
  }
  if (!language().startsWith('zh')) return message
  if (Object.hasOwn(ZH, message)) return t(message)
  for (const [pattern, template] of HOST_ERRORS) {
    if (pattern.test(message)) return message.replace(pattern, template)
  }
  return message
}

// The active DSH language tag, for dates and times.
export function language() {
  const active = service?.getLocale?.().active
  return typeof active === 'string' ? active : 'en'
}

export const dateLocale = () => (language().startsWith('zh') ? 'zh-CN' : 'en-US')

// Translations for the tests: the Chinese dictionary itself.
export const DICTIONARY = { zh: ZH }
